  list=new ListView(context);MediaListStyle.apply(list);list.setAdapter(adapter);body.addView(list,new LayoutParams(-1,0,1));list.setOnItemClickListener((p,v,position,id)->{FavoriteLists.Item item=visible.get(position);if(item.file!=null&&item.file.folder){folders.add(item.file);search.setText("");actions.searchCleared();loadFolder();}else actions.play(item,queue());});
  list.setOnItemLongClickListener((p,v,position,id)->{FavoriteLists.Item item=visible.get(position);PopupMenu menu=new StablePopupMenu(context,v);MediaDownloads.add(menu,getContext(),item);FavoritePicker.podcast(menu,actions.library(),actions::save,item,this::refresh);boolean saved=FavoriteLists.contains(actions.library(),item);menu.getMenu().add(UiText.text(saved?"Fjern fra favoritter":"Tilføj til favoritter")).setOnMenuItemClickListener(choice->{if(saved){actions.save(()->{int tv=tvListIndex();if(tv>=0&&item.stream!=null&&item.stream.channel.kind==Playlist.Kind.TV)TvFavorites.remove(actions.library(),item.stream,tv);else FavoriteLists.remove(actions.library(),item);});refresh();}else FavoritePicker.show(context,actions.library(),actions::save,item,this::refresh);return true;});if(saved&&item.radio!=null)menu.getMenu().add(UiText.text("Omdøb")).setOnMenuItemClickListener(choice->{EditText name=new EditText(getContext());name.setSingleLine();name.setText(item.name());new androidx.appcompat.app.AlertDialog.Builder(getContext()).setTitle(UiText.text("Omdøb")).setView(name).setNegativeButton(UiText.text("Annuller"),null).setPositiveButton(UiText.text("Gem"),(dialog,which)->{if(!name.getText().toString().trim().isEmpty()){actions.save(()->actions.library().renameRadio(item.radio.id,name.getText().toString()));refresh();}}).show();return true;});if(saved)menu.getMenu().add(UiText.text("Vælg favoritliste")).setOnMenuItemClickListener(choice->{FavoritePicker.show(context,actions.library(),actions::save,item,this::refresh);return true;});if(saved&&folders.isEmpty()){if(position>0)menu.getMenu().add(UiText.text("Flyt op")).setOnMenuItemClickListener(choice->{actions.save(()->FavoriteLists.move(actions.library(),category,item,-1));refresh();return true;});if(position<visible.size()-1)menu.getMenu().add(UiText.text("Flyt ned")).setOnMenuItemClickListener(choice->{actions.save(()->FavoriteLists.move(actions.library(),category,item,1));refresh();return true;});}menu.show();return true;});showHome();
